insert into environments(id,name,owner) values ('10000000-0000-4000-8000-000000000001','Demo reporting','Morgan'),('10000000-0000-4000-8000-000000000002','Demo orders','Ari') on conflict do nothing;
insert into changes(id,code,title,environment_id,owner,due_date,risk) values('20000000-0000-4000-8000-000000000001','DEMO-001','Add dispatch marker','10000000-0000-4000-8000-000000000001','Morgan',current_date+(-4),'high') on conflict do nothing;
insert into versions(id,change_id,version,digest,specification,reason,author) values('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',1,'8a5d12d8aa5368ea96ce79b91f7298f7bf8e0295da698b3d44027369f380af00','{"baseline":"create table orders (id integer primary key, reference text not null); insert into orders values (1,''DEMO-01'');","forward":"alter table orders add column dispatched boolean not null default false;","verify":"select count(*)=1 and bool_and(dispatched=false) as ok from orders;","rollback":"alter table orders drop column dispatched;","verify_rollback":"select count(*)=1 and bool_and(reference=''DEMO-01'') as ok from orders;","impact":"Adds a dispatch marker. Demo-only fixture. Production baseline and rollback data loss need separate review.","recovery":"Restore the pre-change backup if new dispatch values must be retained. Rehearsal checks the supplied baseline only."}','Synthetic demo only','Morgan') on conflict do nothing;
