insert into versions(id,change_id,version,digest,specification,reason,author) values('30000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',1,'adb157471b3e7ba03fc57c0a545fca3af03e04a973806a56c04d6527c0320893','{"baseline":"create table orders (id integer primary key, reference text not null); insert into orders values (1,''DEMO-01'');","forward":"create index orders_reference_idx on orders(reference);","verify":"select count(*)=1 as ok from pg_indexes where indexname=''orders_reference_idx'';","rollback":"drop index orders_reference_idx;","verify_rollback":"select count(*)=0 as ok from pg_indexes where indexname=''orders_reference_idx'';","impact":"Adds an index for the synthetic reporting fixture.","recovery":"Restore the pre-change backup if new dispatch values must be retained. Rehearsal checks the supplied baseline only."}','Synthetic demo only','Ari') on conflict do nothing;
