insert into versions(id,change_id,version,digest,specification,reason,author) values('30000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000003',1,'366c716269cac27c61fd3cec79f841099c5678de5b26891a9144a8963b034ac1','{"baseline":"create table orders (id integer primary key, reference text not null); insert into orders values (1,''DEMO-01'');","forward":"alter table orders add column dispatched boolean not null default false;","verify":"select false as ok;","rollback":"alter table orders drop column dispatched;","verify_rollback":"select count(*)=1 and bool_and(reference=''DEMO-01'') as ok from orders;","impact":"Deliberately failing synthetic assertion for attention review.","recovery":"Restore the pre-change backup if new dispatch values must be retained. Rehearsal checks the supplied baseline only."}','Synthetic demo only','Morgan') on conflict do nothing;
